<style>
@page{size:letter;margin:12mm}*{box-sizing:border-box}body{font:10px Arial,sans-serif;line-height:1.4;color:#222;margin:0}header{display:flex;align-items:center;justify-content:space-between;gap:12mm;margin-bottom:5mm}header img{width:46mm}h1{font-size:17px;font-weight:normal;text-align:center;margin:2mm 0}h2{font-size:12px;font-weight:normal;text-align:center;margin:5mm 0 2mm}table{border-collapse:collapse;width:100%;table-layout:fixed}td,th{border:1px solid #222;padding:1.5mm;vertical-align:top;overflow-wrap:anywhere}th,.band{background:#bcbec0;color:#111;font-weight:normal}tbody.stripes tr:nth-child(even){background:#e6e6e6}thead{display:table-header-group}tr,.signature,.keep{break-inside:avoid}p{margin:2mm 0}.label{font-size:7px;color:#444;display:block}.value{min-height:4mm;display:block}.notice{border:1px solid #b99457;background:#fff8e8;padding:2mm;margin-bottom:3mm;font-size:9px}.page{break-before:page}.meta{font-size:8px}.signatures{display:flex;gap:10mm;margin-top:12mm}.signature{flex:1;text-align:center;border-top:1px solid #222;padding:1mm}.contract{font-size:7.3px;line-height:1.65;text-align:justify}.contract p{margin:0 0 1.6mm}.sign-block{border:1px solid #222;min-height:31mm;padding:1.5mm;margin:2mm 0;display:flex;gap:5mm;break-inside:avoid}.sign-block p{margin:1mm 0}.sign-block .details{flex:1}.finger{border:1px solid #222;width:27mm;min-height:27mm;text-align:center}.legal{white-space:pre-line}.footer{font-size:7px;margin-top:4mm}.section-title{background:#bcbec0;text-align:center;border:1px solid #222;padding:.5mm;font-size:10px}.tiny{font-size:7px}@media print{.no-print{display:none}}
</style>
